package common

import("bytes";"encoding/json";"fmt";"net/http";"net/url";"strings";"time")
type MatrixAdapter struct{BaseURL,Token string;Client *http.Client}
func(a MatrixAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){event:=payload;if nested,ok:=payload["event"].(map[string]any);ok{event=nested};content,_:=event["content"].(map[string]any);room,_:=event["room_id"].(string);if room==""{room,_=payload["room_id"].(string)};if room==""{return InboundEvent{},fmt.Errorf("Matrix event has no room_id")};sender:=fmt.Sprint(event["sender"]);if sender=="<nil>"{sender=fmt.Sprint(payload["user_id"])};kind:=map[string]string{"m.image":"image","m.audio":"audio","m.video":"video","m.file":"file"}[fmt.Sprint(content["msgtype"])];if kind==""{kind="text"};return InboundEvent{Platform:"matrix",UserID:sender,ReplyTarget:room,ContentType:kind,Text:fmt.Sprint(content["body"]),MediaURL:fmt.Sprint(content["url"])},nil}
func(a MatrixAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for i,message:=range reply.Messages{content:=map[string]any{"msgtype":"m.text","body":message.Text};if message.Type!="text"{content=map[string]any{"msgtype":"m."+message.Type,"body":message.Text,"url":message.MediaURL}};data,_:=json.Marshal(content);req,_:=http.NewRequest(http.MethodPut,strings.TrimRight(a.BaseURL,"/")+"/_matrix/client/v3/rooms/"+url.PathEscape(event.ReplyTarget)+"/send/m.room.message/bot-"+fmt.Sprint(time.Now().UnixNano())+fmt.Sprint(i),bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Matrix API returned %s",resp.Status)}};return nil}
